from fastapi import APIRouter, WebSocket
from typing import Dict

router = APIRouter(prefix="/crdt/presence")

ROOM_AWARENESS: Dict[str, Dict[str, dict]] = {}

@router.websocket("/rooms/{room_id}/awareness")
async def stream_crdt_presence(
    websocket: WebSocket,
    room_id: str
):
    await websocket.accept()
    token = websocket.headers.get("Authorization", "").replace("Bearer ", "")
    user = authenticate_user_token(token)
    if not user or not user_can_access_room(user.id, room_id):
        await websocket.close(code=1008)
        return

    if room_id not in ROOM_AWARENESS:
        ROOM_AWARENESS[room_id] = {}

    await websocket.send_json({"room": room_id, "active_users": ROOM_AWARENESS[room_id]})
